const { expect } = require("chai");
const { ethers } = require("hardhat");
const {
  loadFixture,
} = require("@nomicfoundation/hardhat-network-helpers");

describe("MyToken Contract", function () {
  // Fixture for test setup
  async function deployTokenFixture() {
    const [owner, addr1, addr2] = await ethers.getSigners();
    const Token = await ethers.getContractFactory("MyToken");
    const token = await Token.deploy("MyToken", "MTK", 18, 1000000);
    return { token, owner, addr1, addr2 };
  }

  describe("Deployment", function () {
    it("Should set name, symbol, decimals", async function () {
      const { token } = await loadFixture(deployTokenFixture);
      expect(await token.name()).to.equal("MyToken");
      expect(await token.symbol()).to.equal("MTK");
      expect(await token.decimals()).to.equal(18);
    });

    it("Should mint initial supply to owner", async function () {
      const { token, owner } = await loadFixture(deployTokenFixture);
      const ownerBalance = await token.balanceOf(owner.address);
      expect(await token.totalSupply()).to.equal(ownerBalance);
    });
  });

  describe("Transfer", function () {
    it("Should transfer tokens between accounts", async function () {
      const { token, owner, addr1 } = await loadFixture(deployTokenFixture);
      await expect(token.transfer(addr1.address, 100)).to.changeTokenBalances(
        token,
        [owner, addr1],
        [-100, 100]
      );
    });

    it("Should fail if sender has insufficient balance", async function () {
      const { token, addr1, owner } = await loadFixture(deployTokenFixture);
      await expect(
        token.connect(addr1).transfer(owner.address, 1)
      ).to.be.revertedWith("ERC20: transfer amount exceeds balance");
    });

    it("Should emit Transfer event", async function () {
      const { token, owner, addr1 } = await loadFixture(deployTokenFixture);
      await expect(token.transfer(addr1.address, 50))
        .to.emit(token, "Transfer")
        .withArgs(owner.address, addr1.address, 50);
    });
  });

  describe("Approve and Allowance", function () {
    it("Should approve tokens for delegation", async function () {
      const { token, owner, addr1 } = await loadFixture(deployTokenFixture);
      await token.approve(addr1.address, 100);
      expect(await token.allowance(owner.address, addr1.address)).to.equal(100);
    });

    it("Should execute transferFrom using allowance", async function () {
      const { token, owner, addr1, addr2 } = await loadFixture(deployTokenFixture);
      await token.approve(addr1.address, 100);
      await token.connect(addr1).transferFrom(owner.address, addr2.address, 50);
      expect(await token.balanceOf(addr2.address)).to.equal(50);
    });

    it("Should fail if allowance is insufficient", async function () {
      const { token, owner, addr1, addr2 } = await loadFixture(deployTokenFixture);
      await token.approve(addr1.address, 50);
      await expect(
        token.connect(addr1).transferFrom(owner.address, addr2.address, 100)
      ).to.be.revertedWith("ERC20: insufficient allowance");
    });
  });

  describe("Mint and Burn (if applicable)", function () {
    it("Owner can mint tokens", async function () {
      const { token, owner, addr1 } = await loadFixture(deployTokenFixture);
      await token.mint(addr1.address, 500);
      expect(await token.balanceOf(addr1.address)).to.equal(500);
      expect(await token.totalSupply()).to.equal(1000500);
    });

    it("Non-owner cannot mint", async function () {
      const { token, addr1 } = await loadFixture(deployTokenFixture);
      await expect(
        token.connect(addr1).mint(addr1.address, 100)
      ).to.be.revertedWith("Ownable: caller is not the owner");
    });

    it("Burn reduces total supply", async function () {
      const { token, owner } = await loadFixture(deployTokenFixture);
      await token.burn(owner.address, 100);
      expect(await token.totalSupply()).to.equal(999900);
    });
  });

  describe("Gas optimization", function () {
    it("Transfer function should stay under gas limit", async function () {
      const { token, owner, addr1 } = await loadFixture(deployTokenFixture);
      const tx = await token.transfer(addr1.address, 100);
      const receipt = await tx.wait();
      expect(receipt.gasUsed).to.be.lessThan(50000);
    });
  });
});
